<template>
  <div class="edoc-tax-mapping-table q-mb-xl">
    <div class="row items-center q-mb-sm">
      <div class="text-subtitle2">{{ $t('edoc_tax_mapping_title') }}</div>
      <q-space />
      <f-btn
        :label="$t('add_mapping')"
        icon="add"
        @click="showAddDialog = true"
      />
    </div>

    <div class="text-caption text-grey-7 q-mb-sm">
      {{ $t('edoc_tax_mapping_description') }}
    </div>

    <q-table
      :rows="rows"
      :columns="columns"
      row-key="id"
      flat
      bordered
      dense
      binary-state-sort
      :pagination="{ rowsPerPage: 0 }"
      hide-bottom
    >
      <template v-slot:body-cell-erp_tax_code="props">
        <q-td :props="props">
          <template v-if="props.row.erp_tax_code">
            {{ props.row.erp_tax_code }}
          </template>
          <q-badge v-else color="orange" outline>
            {{ $t('edoc_tax_mapping_allowed_unmapped') }}
          </q-badge>
        </q-td>
      </template>
      <template v-slot:body-cell-sub_org_id="props">
        <q-td :props="props">
          {{
            props.row.sub_org_id
              ? dropdown_store.getSubOrgName(props.row.sub_org_id) ||
                props.row.sub_org_id
              : '—'
          }}
        </q-td>
      </template>
      <template v-slot:body-cell-is_active="props">
        <q-td :props="props">
          <q-icon
            :name="props.row.is_active ? 'check_circle' : 'cancel'"
            :color="props.row.is_active ? 'positive' : 'grey'"
          />
        </q-td>
      </template>
      <template v-slot:body-cell-actions="props">
        <q-td :props="props" class="text-right">
          <q-btn
            flat
            round
            dense
            color="negative"
            icon="delete"
            @click="confirmDelete(props.row)"
          >
            <q-tooltip>{{ $t('delete') }}</q-tooltip>
          </q-btn>
        </q-td>
      </template>
    </q-table>

    <!-- Add Dialog -->
    <q-dialog v-model="showAddDialog" persistent>
      <q-card style="min-width: 440px">
        <q-card-section>
          <div class="text-h6">{{ $t('edoc_tax_mapping_add') }}</div>
        </q-card-section>

        <q-card-section class="q-pt-none">
          <q-form ref="addForm" @submit.prevent="addEntry">
          <q-input
            v-model="newEntry.tax_country"
            :label="$t('edoc_tax_mapping_country')"
            :hint="$t('edoc_tax_mapping_country_hint')"
            outlined
            dense
            maxlength="2"
            class="q-mb-md"
            autofocus
            lazy-rules
            :rules="[(val) => !!(val && val.trim()) || $t('field_required')]"
          />
          <q-select
            v-model="newEntry.en16931_category"
            :options="categoryOptions"
            :label="$t('edoc_tax_mapping_category')"
            outlined
            dense
            emit-value
            map-options
            class="q-mb-md"
          />
          <q-input
            v-model="newEntry.tax_rate"
            :label="$t('edoc_tax_mapping_rate')"
            :hint="$t('edoc_tax_mapping_rate_hint')"
            type="number"
            step="0.01"
            outlined
            dense
            class="q-mb-md"
          />
          <q-input
            v-model="newEntry.erp_tax_code"
            :label="$t('edoc_tax_mapping_erp_code')"
            :hint="$t('edoc_tax_mapping_erp_code_hint')"
            outlined
            dense
            class="q-mb-md"
          />
          <q-select
            v-model="newEntry.sub_org_id"
            :options="subOrgList"
            :label="$t('sub_organizations')"
            :loading="sub_org_list_loading"
            outlined
            dense
            clearable
            emit-value
            map-options
            popup-content-class="dropdown-fit"
          />
          </q-form>
        </q-card-section>

        <q-card-actions align="right" class="text-primary">
          <q-btn flat :label="$t('Cancel')" @click="cancelAdd" :disable="saving" />
          <q-btn
            flat
            :label="$t('Add')"
            @click="addEntry"
            :loading="saving"
            :disable="saving"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { useQuasar } from 'quasar';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { eDocTaxMappingApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions';
import { useDropdownStore } from 'src/store/main';

const $q = useQuasar();
const dropdown_store = useDropdownStore();
const { subOrgList, sub_org_list_loading } = storeToRefs(dropdown_store);

interface EDocTaxMapping {
  id: string;
  tax_country: string;
  en16931_category: string;
  tax_rate: string | null;
  erp_tax_code: string | null;
  sub_org_id: string | null;
  is_active: boolean;
}

const rows = ref<EDocTaxMapping[]>([]);
const showAddDialog = ref(false);
const saving = ref(false);
const addForm = ref();

const emptyEntry = () => ({
  tax_country: '',
  en16931_category: 'S',
  tax_rate: '',
  erp_tax_code: '',
  sub_org_id: null as string | null,
});
const newEntry = ref(emptyEntry());

// UNTDID 5305 duty/tax/fee category codes used by EN16931 e-invoices.
const categoryOptions = [
  { label: 'S — Standard rate', value: 'S' },
  { label: 'AA — Lower rate', value: 'AA' },
  { label: 'Z — Zero rated', value: 'Z' },
  { label: 'E — Exempt from tax', value: 'E' },
  { label: 'AE — VAT reverse charge', value: 'AE' },
  { label: 'K — Intra-community exempt', value: 'K' },
  { label: 'G — Export outside the EU', value: 'G' },
  { label: 'O — Outside scope of tax', value: 'O' },
  { label: 'L — Canary Islands (IGIC)', value: 'L' },
  { label: 'M — Ceuta/Melilla (IPSI)', value: 'M' },
];

const columns = [
  {
    name: 'tax_country',
    label: i18n.t('edoc_tax_mapping_country'),
    field: 'tax_country',
    align: 'left',
    sortable: true,
  },
  {
    name: 'en16931_category',
    label: i18n.t('edoc_tax_mapping_category'),
    field: 'en16931_category',
    align: 'left',
    sortable: true,
  },
  {
    name: 'tax_rate',
    label: i18n.t('edoc_tax_mapping_rate'),
    field: 'tax_rate',
    align: 'left',
    sortable: true,
  },
  {
    name: 'erp_tax_code',
    label: i18n.t('edoc_tax_mapping_erp_code'),
    field: 'erp_tax_code',
    align: 'left',
    sortable: true,
  },
  {
    name: 'sub_org_id',
    label: i18n.t('sub_organizations'),
    field: 'sub_org_id',
    align: 'left',
    sortable: true,
  },
  {
    name: 'is_active',
    label: i18n.t('active'),
    field: 'is_active',
    align: 'left',
    sortable: true,
  },
  {
    name: 'actions',
    label: '',
    field: 'actions',
    align: 'right',
  },
] as any;

const fetchMappings = async () => {
  try {
    const response = await eDocTaxMappingApiService.listMappings();

    if (response && response.success && Array.isArray(response.data)) {
      rows.value = response.data;
    }
  } catch (error) {
    console.error('Failed to fetch edoc tax mappings:', error);
  }
};

onMounted(() => {
  fetchMappings();
  dropdown_store.getSubOrgsList();
});

const addEntry = async () => {
  // Show the inline "required" message(s) and block the save when invalid.
  const valid = await addForm.value?.validate();
  if (!valid) return;

  saving.value = true;
  try {
    const response = await eDocTaxMappingApiService.upsertMapping({
      tax_country: newEntry.value.tax_country.trim().toUpperCase(),
      en16931_category: newEntry.value.en16931_category,
      tax_rate: newEntry.value.tax_rate || null,
      erp_tax_code: newEntry.value.erp_tax_code.trim() || null,
      sub_org_id: newEntry.value.sub_org_id || null,
    });

    if (response && response.success === false) {
      // Throw so the catch block runs the response through
      // ApiExceptions.getErrorMessage — which translates error_code via i18n.
      // The dialog stays open so the user can fix the input and retry.
      throw response;
    }

    // Success: notify, refresh, reset the form and close the dialog.
    notify.success(i18n.t('mapping_added_successfully'));
    fetchMappings();
    newEntry.value = emptyEntry();
    addForm.value?.resetValidation();
    showAddDialog.value = false;
  } catch (error) {
    // Failure: keep the dialog open with the entered values so the user can
    // correct and resubmit — do NOT reset the form or close the dialog.
    notify.error(
      ApiExceptions.getErrorMessage(error as any) ||
        i18n.t('mapping_add_failed'),
    );
  } finally {
    saving.value = false;
  }
};

const cancelAdd = () => {
  // Clear the form + any validation errors so a reopened dialog starts blank.
  newEntry.value = emptyEntry();
  addForm.value?.resetValidation();
  showAddDialog.value = false;
};

const confirmDelete = (row: EDocTaxMapping) => {
  $q.dialog({
    title: i18n.t('confirm'),
    message: i18n.t('delete_mapping_confirm'),
    cancel: true,
    persistent: true,
  }).onOk(() => {
    deleteEntry(row);
  });
};

const deleteEntry = async (row: EDocTaxMapping) => {
  try {
    const response = await eDocTaxMappingApiService.deleteMapping(row.id);

    if (response && response.success === false) {
      // Throw so the catch block runs the response through
      // ApiExceptions.getErrorMessage — which translates error_code via i18n.
      throw response;
    }

    notify.success(i18n.t('mapping_deleted_successfully'));
    fetchMappings();
  } catch (error) {
    notify.error(
      ApiExceptions.getErrorMessage(error as any) ||
        i18n.t('mapping_delete_failed'),
    );
  }
};
</script>
